<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import {Deck,OrbitView,COORDINATE_SYSTEM,AmbientLight,DirectionalLight,LightingEffect} from '@deck.gl/core';
import {PathLayer,PolygonLayer,ScatterplotLayer,TextLayer} from '@deck.gl/layers';
import {renderIdentity,elevationAt,surfaceTriangles,contourSegments,cityBlocks,concentrationColor,concentrationColumns,squareCells,dataBounds} from './mapGeometry';
const props=defineProps({decision:Object,planning:Object,display:Object,model:Object,frame:Object,identity:Object,layers:Object,viewMode:{default:'3d'},follow:{default:false},comparisonModel:Object,comparisonFrame:Object});
const emit=defineEmits(['pick','renderStatus']);const host=ref(),error=ref('');let deck,observer,viewState,cameraTimer,lastFocus='activity',frames=0,disposed=false;
const EXAGGERATION=4;
const terrain=computed(()=>props.display?surfaceTriangles(props.display,EXAGGERATION):[]);
const contours=computed(()=>contourSegments(terrain.value,EXAGGERATION));
const buildings=computed(()=>props.display?cityBlocks(props.display,props.identity?.seed??0):[]);
const z=(p,extra=8)=>elevationAt(props.display,p[0],p[1])*EXAGGERATION+extra;
const lift=points=>points.map(p=>[p[0],p[1],z(p)]);
const common=()=>({coordinateSystem:COORDINATE_SYSTEM.CARTESIAN,pickable:true,onClick:info=>{if(info.object)emit('pick',info.object);},autoHighlight:true,highlightColor:[255,255,200,100]});
function polygon(id,data,getColor,extra={}){return new PolygonLayer({...common(),id,data,getPolygon:d=>d.points.map(p=>p.length===3?p:[...p,z(p)]),getFillColor:getColor,stroked:false,...extra});}
function path(id,data,color,width=3){return new PathLayer({...common(),id,data,getPath:d=>lift(d.points_m??d.points),getColor:color,getWidth:width,widthUnits:'pixels',widthMinPixels:1,jointRounded:true,capRounded:true});}
function point(id,data,color,radius=6){return new ScatterplotLayer({...common(),id,data,getPosition:d=>[...d.position_m,z(d.position_m,18)],getFillColor:color,getRadius:radius,radiusUnits:'pixels',radiusMinPixels:radius,stroked:true,getLineColor:[5,20,28],lineWidthUnits:'pixels',getLineWidth:1});}
function draw(){if(!deck||!props.display)return;try{renderIdentity(props.model,props.frame);if(props.frame&&props.identity){for(const k of ['scenario_id','scenario_version','run_id','manifest_sha256','network_sha256'])if(props.frame.identity[k]!==props.identity[k])throw Error('MAP_VIEW_IDENTITY_MISMATCH: '+k);}
 const d=props.display,f=props.frame,visible=props.layers??{},items=[];
 const extent=d.extent_m;items.push(polygon('service-domain',[{kind:'boundary',id:'100km-service',points:[[extent[0],extent[1],-20],[extent[2],extent[1],-20],[extent[2],extent[3],-20],[extent[0],extent[3],-20]]}],[28,49,50]));
 if(visible.terrain!==false&&terrain.value.length)items.push(polygon('terrain-surface',terrain.value,t=>{const h=Math.max(0,Math.min(1,t.elevation_m/850));return [55+125*h,88+65*h,68+35*h,255];}));
 if(visible.terrain!==false&&contours.value.length)items.push(path('terrain-derived-contours',contours.value,[207,196,145,100],1));
 if(visible.terrain!==false&&d.terrain)items.push(new TextLayer({...common(),id:'terrain-region-labels',data:d.terrain.regions.map(r=>{const b=dataBounds(r.polygon_m),p=[(b[0]+b[2])/2,(b[1]+b[3])/2];return {...r,kind:'terrain-region',position_m:p,label:({plain:'平原',hillside:'山坡',mountain:'山地'})[r.kind]};}),getPosition:r=>[...r.position_m,z(r.position_m,50)],getText:r=>r.label,getColor:[235,230,194],getSize:15,fontFamily:'Arial, Microsoft YaHei, sans-serif',characterSet:'auto',background:true,getBackgroundColor:[15,32,30,170]}));
 if(visible.water!==false)items.push(polygon('river-water',d.rivers.map(r=>({...r,kind:'river',points:r.polygon_m.map(p=>[...p,z(p,2)])})),[40,128,173,235]));
 if(visible.buildings!==false){items.push(polygon('city-zones',d.cities.map(c=>({...c,kind:'city',points:c.polygon_m})),[140,152,142,35],{filled:false,stroked:true,getLineColor:[180,180,140,70],lineWidthUnits:'pixels',getLineWidth:1}));items.push(polygon('synthetic-buildings',buildings.value.filter((b,i)=>viewState?.zoom>-6.5?Math.hypot(b.points[0][0]-viewState.target[0],b.points[0][1]-viewState.target[1])<18000:i%8===0),[173,184,168],{extruded:true,getElevation:b=>b.height_m*EXAGGERATION,material:{ambient:.45,diffuse:.7,shininess:15}}));}
 if(visible.buildings!==false)items.push(new TextLayer({...common(),id:'settlement-labels',data:d.cities.map(c=>{const b=dataBounds(c.polygon_m);return {...c,kind:'settlement',position_m:[(b[0]+b[2])/2,(b[1]+b[3])/2]};}),getPosition:c=>[...c.position_m,z(c.position_m,100)],getText:c=>c.label,getSize:14,getColor:[242,235,216],fontFamily:'Arial, Microsoft YaHei, sans-serif',characterSet:'auto'}));
 if(visible.roads!==false){const roads=props.model?.roads??d.roads.map(r=>({...r,points_m:r.points}));items.push(path('road-lane-geometry',roads.map(r=>({...r,kind:'road',id:r.edge_id})),r=>r.road_class==='arterial'?[185,199,180]:r.road_class==='collector'?[150,170,157]:[107,132,123],2));items.push(path('bridge-geometry',d.bridges.map(b=>({...b,kind:'bridge',points_m:b.line_m})),[224,201,142],4));}

 if(visible.congestion!==false&&f?.edgeStates?.length)items.push(path('observed-edge-states',f.edgeStates,e=>e.quality!=='observed'?[115,125,130]:e.congested?[240,80,65]:[65,200,170],7));
 if(visible.background!==false&&f?.backgroundVehicles?.length)items.push(point('background-vehicles',f.backgroundVehicles.map(v=>({...v,kind:'background-vehicle',id:v.vehicle_id})),[70,155,245],4));
 if(props.decision){items.push(path('decision-old-path',props.decision.old_paths.map(points_m=>({kind:'decision-old',points_m})),[215,225,235],7));items.push(path('decision-new-path',props.decision.new_paths.map(points_m=>({kind:'decision-new',points_m})),[240,120,245],5));}
 if(props.comparisonFrame){renderIdentity(props.comparisonModel,props.comparisonFrame);items.push(path('comparison-actual-trails',props.comparisonFrame.paths.actual.map(p=>({...p,kind:'comparison-trail',id:p.key,comparison_run_id:props.comparisonFrame.identity.run_id})),[198,207,210,160],3));}
 if(visible.planned!==false&&f)items.push(path('planned-routes',f.paths.planned.map(p=>({...p,kind:'planned-route',id:p.key})),[78,164,255],4));
 if(visible.actual!==false&&f)items.push(path('actual-trails',f.paths.actual.map(p=>({...p,kind:'actual-trail',id:p.key})),[255,191,83],5));
 if(visible.replanned!==false&&f)items.push(path('replanned-routes',f.paths.replanned.map(p=>({...p,kind:'replanned-route',id:p.key})),[229,113,255],4));
 if(visible.closures!==false&&f)items.push(path('active-closures',f.closures.filter(c=>c.active).map(c=>({...c,kind:'closure',id:c.edge_id})),[255,86,83],7));
 if(visible.pollution!==false&&f?.concentration?.placement==='synthetic_view_only'){const cells=squareCells(concentrationColumns(f.concentration));items.push(polygon('concentration-xy-max',cells,c=>concentrationColor(c.concentration_mg_L)));if(visible.threshold!==false)items.push(polygon('threshold-region',cells.filter(c=>c.exceeds_threshold),[255,92,35,80],{stroked:true,getLineColor:[255,210,105,220],lineWidthUnits:'pixels',getLineWidth:1}));}
 if(visible.facilities!==false){items.push(point('depots',d.depots.map(p=>({...p,id:p.depot_id,kind:'depot',position_m:[p.position_m.x_m,p.position_m.y_m]})),[75,230,196],7));items.push(point('wells',d.wells.map(p=>({...p,id:p.well_id,kind:'well',position_m:[p.position_m.x_m,p.position_m.y_m],task_state:f?.taskStates.find(t=>t.well_id===p.well_id)?.state??'input',tasks:f?.taskStates.filter(t=>t.well_id===p.well_id)??[],events:f?.taskEvents.filter(t=>t.well_id===p.well_id)??[]})),[200,157,249],8));}
 if(visible.vehicles!==false&&f){items.push(point('vehicles',f.vehicles.map(v=>({...v,kind:'vehicle',id:v.vehicle_id})),[255,207,99],7));items.push(new TextLayer({...common(),id:'vehicle-labels',data:f.vehicles,getPosition:v=>[...v.position_m,z(v.position_m,26)],getText:v=>v.vehicle_id,getSize:12,getColor:[252,236,194],getPixelOffset:[0,-17],fontFamily:'Arial, Microsoft YaHei, sans-serif',characterSet:'auto',background:true,getBackgroundColor:[8,24,31,190]}));}
 if(visible.inputVehicles&&!f)items.push(point('input-vehicles',d.vehicles.map(v=>({...v,id:v.vehicle_id,kind:'initial_vehicle',position_m:[v.position_m.x_m,v.position_m.y_m]})),[159,171,174],5));
 deck.setProps({layers:items});error.value='';
 }catch(e){error.value=e.message;deck.setProps({layers:[]});emit('renderStatus',{state:'ERROR',message:e.message});}}
function fit(mode='activity'){
 if(!props.display||!deck)return;lastFocus=mode;let bounds=props.display.extent_m;
 if(mode==='mountain'){const region=props.display.terrain?.regions.find(r=>r.kind==='mountain');if(region)bounds=dataBounds(region.polygon_m,bounds);}
 else if(mode==='pollution'&&props.frame?.concentration?.placement==='synthetic_view_only')bounds=dataBounds(props.frame.concentration.cells.map(c=>c.position_m).filter(Boolean),bounds);
 else if(mode==='activity'){let points=[];const f=props.frame;if(f){points=[...f.paths.planned,...f.paths.actual,...f.paths.replanned].flatMap(p=>p.points_m);points.push(...f.vehicles.map(v=>v.position_m),...f.taskStates.map(t=>t.position_m).filter(Boolean));}if(!points.length)points=(props.model?.roads??props.display.roads).flatMap(r=>r.points_m??r.points);bounds=dataBounds(points,bounds);}
 const w=Math.max(600,bounds[2]-bounds[0]),h=Math.max(600,bounds[3]-bounds[1]),size=host.value.getBoundingClientRect();viewState={target:[(bounds[0]+bounds[2])/2,(bounds[1]+bounds[3])/2,elevationAt(props.display,(bounds[0]+bounds[2])/2,(bounds[1]+bounds[3])/2)*EXAGGERATION+20],zoom:Math.log2(Math.min(size.width/w,size.height/(h*(props.viewMode==='3d'?.82:1)))*.78),rotationX:props.viewMode==='3d'?55:90,rotationOrbit:0,minZoom:-12,maxZoom:3};deck.setProps({viewState});}
function debug(){if(!deck)return null;return {frames,viewState,layer_ids:deck.props.layers.map(x=>x.id),layer_counts:Object.fromEntries(deck.props.layers.map(x=>[x.id,x.props.data?.length??0])),scenario_time_s:props.frame?.scenario_time_s,concentration_frame_index:props.frame?.concentration?.frame_index,concentration_cells:props.frame?.concentration?.placement==='synthetic_view_only'?concentrationColumns(props.frame.concentration):[],vehicle_positions:props.frame?.vehicles.map(v=>({id:v.vehicle_id,position_m:v.position_m}))??[],identity:props.identity,vehicle_ids:props.frame?.vehicles.map(v=>v.vehicle_id)??[],background_ids:props.frame?.backgroundVehicles?.map(v=>v.vehicle_id)??[],congested_edges:props.frame?.edgeStates?.filter(e=>e.congested).map(e=>e.edge_id)??[],project:(position)=>deck.getViewports()[0].project([...position,z(position,18)]),pick:(x,y)=>deck.pickObject({x,y,radius:4})?.object??null};}
onMounted(()=>{try{deck=new Deck({parent:host.value,id:'spatiotemporal-deck-canvas',views:new OrbitView({id:'cartesian-map',controller:true,near:.01,far:100}),controller:true,useDevicePixels:Math.min(devicePixelRatio,2),getCursor:({isDragging,isHovering})=>isDragging?'grabbing':isHovering?'pointer':'grab',effects:[new LightingEffect({ambient:new AmbientLight({intensity:1}),sun:new DirectionalLight({direction:[-1,-2,-3],intensity:1.1})})],onViewStateChange:({viewState:next})=>{viewState=next;deck.setProps({viewState});draw();},onError:e=>{if(disposed)return;error.value=e.message;emit('renderStatus',{state:'ERROR',message:e.message});},onAfterRender:()=>{if(disposed)return;frames++;if(frames===1)emit('renderStatus',{state:'READY',frames});}});observer=new ResizeObserver(()=>{if(deck){deck.setProps({width:'100%',height:'100%'});}});observer.observe(host.value);draw();cameraTimer=setTimeout(()=>{if(!disposed)fit('activity');},100);if(import.meta.env.DEV)window.__BORDEN_MAP__=()=>debug();}catch(e){error.value=e.message;emit('renderStatus',{state:'ERROR',message:e.message});}});
watch(()=>[props.display,props.model],()=>{draw();fit('activity');});watch(()=>[props.frame,props.layers,props.comparisonFrame,props.decision],()=>{draw();if(props.follow&&props.frame?.vehicles.length&&viewState){const p=props.frame.vehicles[0].position_m;viewState={...viewState,target:[...p,z(p)]};deck?.setProps({viewState});}},{deep:false});watch(()=>props.viewMode,()=>{if(viewState)fit(lastFocus);});
onUnmounted(()=>{disposed=true;clearTimeout(cameraTimer);observer?.disconnect();deck?.finalize();deck=null;if(import.meta.env.DEV)delete window.__BORDEN_MAP__;});defineExpose({fit,debug});
</script>
<template><div class="deck-map" ref="host" role="img" aria-label="交通污染应急时空地图"><div v-if="error" class="map-render-error" role="alert">WebGL ERROR · {{error}}</div></div></template>
